# Testo e scaletta visiva del video lungo (un'unica fonte per script.py e scenes.py)
# Caso 031: Lelio Luttazzi, arrestato a Roma nel 1970 per una telefonata fatta per un amico, 27 giorni a Regina Coeli, prosciolto
SC = [
 # 00 INTRO
 (0, "Roma, 1970. Un uomo fa una telefonata per un amico. Un gesto di pochi secondi, come ne facciamo tutti. Poco dopo, per quella telefonata, finisce in carcere.", [('Roma', 'map:Roma|30|Roma'), ('telefonata', 'i:phonecall|UNA TELEFONATA'), ('amico', 'fig:suit|UN FAVORE'), ('carcere', 'i:prison|IN CARCERE')]),
 (0, "Non è un uomo qualunque. È uno dei volti più famosi della radio e della televisione italiana: Lelio Luttazzi, musicista, pianista, la voce della Hit Parade.", [('qualunque', 'i:tuxedo|SAGOMA · NESSUNA FOTO'), ('radio', 'ii:radio|LA RADIO|tvstage|LA TELEVISIONE'), ('Lelio', 'card:LELIO LUTTAZZI|musicista e conduttore|Trieste · 1923'), ('Hit', 'i:hitparade|LA HIT PARADE')]),
 (0, "Resta ventisette giorni a Regina Coeli, in isolamento. Poi gli inquirenti riconoscono che con quella storia non c'entra niente. Ma la sua vita non sarà più la stessa.", [('ventisette', 'big:27 giorni|a Regina Coeli'), ('isolamento', 'i:isolation|IN ISOLAMENTO'), ('niente', 'stamp:ESTRANEO'), ('vita', 'i:question|E DOPO?')]),
 (0, "In questo fascicolo vedremo chi era Luttazzi, l'Italia della radio e della televisione di allora, la telefonata, l'arresto, i giorni in cella, il proscioglimento e quello che è successo dopo.", [('In', 'cover'), ('Luttazzi', 'iii:piano|LA MUSICA|phonecall|LA TELEFONATA|prison|IL CARCERE'), ('proscioglimento', 't:LELIO LUTTAZZI · ROMA 1970')]),
 # 01 L'EPOCA E IL LUOGO
 (1, "Per capire questa storia bisogna immaginare l'Italia di quegli anni. La televisione è una sola, quella pubblica, la Rai, con due canali. E alla sera le famiglie si riuniscono davanti allo stesso schermo.", [('Per', 'tl:1954|LA TV;1967|HIT PARADE;1970|L\'ARRESTO;2009|SANREMO;2010|LA MORTE'), ('televisione', 'i:tv|UNA SOLA TELEVISIONE'), ('canali', 'big:2 canali|la Rai'), ('famiglie', 'i:family|TUTTI DAVANTI ALLO SCHERMO')]),
 (1, "Chi conduce un programma del sabato sera, o un programma della radio ascoltato da milioni di persone, entra in tutte le case. Non è solo famoso: è di famiglia.", [('sabato', 'i:tvstage|IL SABATO SERA'), ('milioni', 'crowd'), ('famiglia', 'h:Una persona\n*di famiglia*')]),
 (1, "Secondo un quotidiano toscano, in quegli anni Luttazzi è considerato uno dei magnifici cinque della televisione italiana, insieme a Corrado, Mike Bongiorno, Pippo Baudo ed Enzo Tortora.", [('quotidiano', 'i:newspaper|SECONDO UN QUOTIDIANO'), ('magnifici', 'big:5|i magnifici cinque'), ('Tortora', 'iii:microphone|CORRADO|microphone|BONGIORNO|microphone|BAUDO · TORTORA')]),
 (1, "Ricordiamoci quest'ultimo nome, Enzo Tortora. Tredici anni dopo, nel 1983, anche lui finirà in carcere da innocente. È un caso che abbiamo raccontato in un altro fascicolo.", [('Tortora', 'i:microphone|ENZO TORTORA'), ('Tredici', 'big:13 anni|dopo · nel 1983'), ('fascicolo', 'stamp:FASCICOLO N. 006')]),
 (1, "E la radio? Nel 1970 la radio è ancora fortissima. I giovani ascoltano le canzoni nuove e aspettano di sapere quali sono le più vendute, le più amate. È proprio lì che Luttazzi ha il suo regno.", [('radio', 'i:radio|LA RADIO'), ('giovani', 'i:music|LE CANZONI NUOVE'), ('regno', 'i:hitparade|IL SUO REGNO')]),
 (1, "Il luogo principale della nostra storia è Roma. Qui ci sono gli studi della televisione e della radio, i teatri, i locali. E qui Luttazzi abita, secondo le ricostruzioni, in un attico vicino alla Fontana di Trevi.", [('Roma', 'map:Roma|40|Roma'), ('studi', 'iii:tvcam|GLI STUDI|clapper|IL CINEMA|music|I LOCALI'), ('attico', 'home:0'), ('Fontana', 'i:fountain|VICINO ALLA FONTANA DI TREVI')]),
 (1, "C'è poi un altro luogo che conta in questa storia: Regina Coeli, il carcere di Roma, nel quartiere di Trastevere, vicino al Tevere. Un nome famoso, che per molti romani significa una cosa sola: la prigione.", [('luogo', 'map:Roma|60|Roma'), ('Regina', 'i:prison|REGINA COELI'), ('Tevere', 'i:river|VICINO AL TEVERE'), ('prigione', 'i:bars|LA PRIGIONE')]),
 (1, "E le leggi? In materia di droga, in Italia vale una legge del 1954. Una legge nuova arriverà solo alla fine del 1975. Nel 1970 la droga è un tema nuovo per i giornali, e fa paura.", [('leggi', 'i:law|LE LEGGI'), ('1954', 'tl:1954|LA LEGGE;1970|L\'ARRESTO;1975|LA LEGGE NUOVA'), ('giornali', 'i:newspaper|UN TEMA NUOVO'), ('paura', 'stamp:PAURA')]),
 (1, "Gli investigatori, allora come oggi, possono mettere sotto controllo i telefoni. Si chiamano intercettazioni. E in questa storia saranno decisive.", [('investigatori', 'i:magnifier|GLI INVESTIGATORI'), ('telefoni', 'i:taperec|I TELEFONI SOTTO CONTROLLO'), ('intercettazioni', 'h:Le *intercettazioni*'), ('decisive', 'stamp:DECISIVE')]),
 (1, "E come si telefona nel 1970? Niente cellulari, niente messaggi scritti. C'è il telefono fisso di casa, con il disco per comporre il numero. Se non sei in casa, risponde chi c'è: un familiare, un ospite, la persona che lavora per te.", [('telefona', 'i:phone|IL TELEFONO FISSO'), ('cellulari', 'stamp:NIENTE CELLULARI'), ('disco', 'i:phonecall|IL DISCO DEI NUMERI'), ('risponde', 'iii:family|UN FAMILIARE|woman|CHI LAVORA IN CASA|question|UN OSPITE')]),
 (1, "Così i messaggi passano di bocca in bocca: chiamalo tu, digli questo, richiamalo stasera. È normale, succede in tutte le case. Ed è proprio un messaggio così, passato da una persona all'altra, che darà inizio a questa storia.", [('messaggi', 'flow:CHI CHIAMA>CHI RISPONDE'), ('normale', 'i:notes|UN BIGLIETTO VICINO AL TELEFONO'), ('inizio', 'stamp:L\'INIZIO')]),
 # 02 I PROTAGONISTI
 (2, "Conosciamo i protagonisti, uno per uno. Al centro c'è lui: Lelio Luttazzi, nato a Trieste il 27 aprile 1923. Nel 1970 ha quarantasette anni ed è all'apice della carriera.", [('Conosciamo', 'board:0'), ('Trieste', 'map:Trieste|40|Trieste'), ('1923', 'cal:TRIESTE|27 APRILE 1923'), ('quarantasette', 'big:47 anni|nel 1970')]),
 (2, "Compositore, pianista, cantante, direttore d'orchestra, attore, conduttore della radio e della televisione. Sempre elegante, sempre in smoking. Un autore televisivo lo chiamerà, scherzando, portatore sano di smoking.", [('Compositore', 'iii:music|COMPOSITORE|piano|PIANISTA|microphone|CONDUTTORE'), ('smoking', 'i:tuxedo|SEMPRE IN SMOKING'), ('portatore', 'h:«Portatore sano\ndi *smoking*»')]),
 (2, "Il secondo protagonista è il suo amico Walter Chiari, attore e comico tra i più popolari d'Italia: ha recitato con Visconti nel film Bellissima e nelle commedie musicali con Delia Scala.", [('secondo', 'board:1'), ('Walter', 'card:WALTER CHIARI|attore e comico|l\'amico'), ('Bellissima', 'ii:clapper|IL CINEMA|tvstage|IL TEATRO')]),
 (2, "Luttazzi e Chiari sono amici da anni. Secondo un quotidiano toscano, la loro amicizia si consolida in Versilia, dove d'estate si esibiscono, a volte da soli e a volte insieme.", [('amici', 'ii:music|LUTTAZZI|clapper|CHIARI'), ('Versilia', 'i:umbrella|LE ESTATI IN VERSILIA'), ('insieme', 'stamp:AMICI')]),
 (2, "Il terzo protagonista è un uomo di cui non diremo il nome: un conoscente di Chiari, che secondo le ricostruzioni spaccia cocaina. Il suo telefono è sotto controllo.", [('terzo', 'board:2'), ('nome', 'i:nophoto|NESSUN NOME'), ('cocaina', 'stamp:SPACCIATORE'), ('telefono', 'i:taperec|IL TELEFONO SOTTO CONTROLLO')]),
 (2, "Il quarto protagonista è la Guardia di Finanza, che conduce l'indagine sulla droga nel mondo dello spettacolo. E con lei la magistratura di Roma, con il pubblico ministero che segue il caso.", [('quarto', 'board:3'), ('Guardia', 'i:gdf|L\'INDAGINE'), ('magistratura', 'i:court|LA MAGISTRATURA DI ROMA')]),
 (2, "Poi ci sono i giornali, che in quei giorni metteranno il nome di Luttazzi in prima pagina. E il pubblico, che lo conosce dalla radio e dalla televisione, e adesso lo legge accanto alla parola droga.", [('giornali', 'board:4'), ('prima', 'i:newspaper|IN PRIMA PAGINA'), ('pubblico', 'crowd'), ('droga', 'stamp:DROGA?')]),
 (2, "E infine c'è una donna che entrerà nella sua vita più tardi, ma che sarà fondamentale per far conoscere questa storia: Rossana Moretti, la sua seconda moglie, che ne custodirà la memoria.", [('infine', 'board:5'), ('Rossana', 'card:ROSSANA LUTTAZZI|la seconda moglie|custode della memoria'), ('memoria', 'i:photos|LA MEMORIA')]),
 (2, "Riassumiamo. Un musicista famosissimo, un amico attore, un conoscente con il telefono controllato, un'indagine, i giornali e il pubblico. Adesso facciamo un passo indietro: a Trieste, durante la guerra.", [('Riassumiamo', 'board:5'), ('musicista', 'iii:piano|IL MUSICISTA|clapper|L\'AMICO|taperec|IL TELEFONO'), ('Trieste', 'map:Trieste|30|Trieste')]),
 # 03 LA CARRIERA: DA TRIESTE ALLA HIT PARADE
 (3, "Lelio Luttazzi cresce a Trieste. La famiglia, secondo le ricostruzioni, lo vorrebbe avvocato, e lui si iscrive a giurisprudenza all'università di Trieste. Ma la sua passione è un'altra: il pianoforte.", [('cresce', 'i:house|TRIESTE'), ('avvocato', 'i:law|GIURISPRUDENZA'), ("all'università", 'i:oldbook|L\'UNIVERSITÀ DI TRIESTE'), ('pianoforte', 'i:piano|LA PASSIONE')]),
 (3, "Durante la guerra suona il pianoforte a Radio Trieste, e scrive le sue prime canzoni. Una di queste, Il giovanotto matto, viene cantata da Ernesto Bonino, una delle voci più note del momento.", [('guerra', 'cal:LA GUERRA|1940-1945'), ('Radio', 'i:radio|RADIO TRIESTE'), ('giovanotto', 'i:music|IL GIOVANOTTO MATTO'), ('Bonino', 'i:microphone|LA CANTA ERNESTO BONINO')]),
 (3, "Le fonti non concordano sull'anno esatto: per alcune è durante la guerra, per un'altra alla fine degli anni Trenta. Secondo le ricostruzioni, l'avrebbe scritta proprio sui libri di diritto.", [("sull'anno", 'stamp:ANNO NON CONCORDE'), ('Trenta', 'tl:1938|?;1940|?;1944|?'), ('diritto', 'i:openbook|SUI LIBRI DI DIRITTO')]),
 (3, "Finita la guerra arriva una sorpresa: una lettera della società degli autori con i diritti d'autore delle sue canzoni. Una somma importante, circa trecentocinquantamila lire secondo le fonti. È il segnale: farà il musicista.", [('sorpresa', 'i:envelope|UNA LETTERA'), ("d'autore", 'i:music|I DIRITTI D\'AUTORE'), ('trecentocinquantamila', 'big:≈ 350.000 lire|i primi diritti d\'autore'), ('musicista', 'stamp:FARÀ IL MUSICISTA')]),
 (3, "Si trasferisce a Milano, dove lavora con il cantante Teddy Reno nel mondo dei dischi. Scrive per lui Muleta mia, una canzone che secondo le ricostruzioni è tra le prime a portare il jazz dentro la canzone italiana.", [('Milano', 'map:Milano|12|Trieste,Milano|Trieste>Milano'), ('Teddy', 'i:microphone|TEDDY RENO'), ('Muleta', 'i:music|MULETA MIA'), ('jazz', 'h:Il *jazz*\nnella canzone')]),
 (3, "Scrive anche per il teatro di rivista, gli spettacoli con canzoni, ballerine e comici che riempiono i teatri del dopoguerra. Fa le musiche di Barbanera bel tempo si spera, con Ugo Tognazzi, e di Tutte donne meno io, con Macario.", [('teatro', 'i:tvstage|IL TEATRO DI RIVISTA'), ('Barbanera', 'i:music|BARBANERA BEL TEMPO SI SPERA'), ('Tognazzi', 'ii:microphone|UGO TOGNAZZI|microphone|MACARIO')]),
 (3, "È il periodo in cui la canzone italiana cambia. Accanto alle melodie tradizionali arrivano il ritmo e l'ironia. E Luttazzi, con il suo pianoforte, è uno di quelli che porta questa novità alla radio e nei dischi.", [('cambia', 'h:La canzone\n*cambia*'), ('ritmo', 'ii:music|LA MELODIA|piano|IL RITMO'), ('dischi', 'i:radio|RADIO E DISCHI')]),
 (3, "Il jazz, secondo le ricostruzioni, lo ha imparato a Trieste, dagli americani e dalla loro musica. Lo swing diventa il suo marchio: canzoni leggere, ritmate, ironiche.", [('jazz', 'i:piano|LO SWING'), ('americani', 'i:radio|LA MUSICA AMERICANA'), ('ironiche', 'iii:music|LEGGERE|music|RITMATE|music|IRONICHE')]),
 (3, "Arrivano i successi. Souvenir d'Italie. Una zebra a pois, cantata da Mina. Canto anche se sono stonato. El can de Trieste, in dialetto triestino. Ancora oggi molti le canticchiano senza sapere chi le ha scritte.", [('successi', 'h:I *successi*'), ('Souvenir', 'i:music|SOUVENIR D\'ITALIE'), ('zebra', 'i:microphone|UNA ZEBRA A POIS · MINA'), ('Trieste', 'i:music|EL CAN DE TRIESTE')]),
 (3, "Lavora anche per il cinema. Scrive musiche per film con Totò, e come attore compare in film importanti: nel 1960 in L'avventura di Michelangelo Antonioni, nel 1965 in L'ombrellone di Dino Risi.", [('cinema', 'i:filmreel|IL CINEMA'), ('Totò', 'i:clapper|MUSICHE PER I FILM CON TOTÒ'), ("L'avventura", 'cal:L\'AVVENTURA|1960'), ("L'ombrellone", 'i:umbrella|L\'OMBRELLONE · 1965')]),
 (3, "Tra i film con Totò per cui scrive le musiche c'è Totò, Peppino e la malafemmina, uno dei più famosi della coppia con Peppino De Filippo. Le sue note accompagnano le risate di milioni di spettatori.", [('Totò', 'i:clapper|TOTÒ, PEPPINO E LA MALAFEMMINA'), ('famosi', 'i:cinema|AL CINEMA'), ('milioni', 'crowd')]),
 (3, "Poi arriva la televisione. Luttazzi conduce programmi musicali e di varietà, e diventa uno dei volti di Studio Uno, il grande varietà della Rai del sabato sera, accanto a Mina.", [('televisione', 'i:tv|LA TELEVISIONE'), ('varietà', 'i:tvstage|IL VARIETÀ'), ('Studio', 'h:*Studio Uno*'), ('Mina', 'i:microphone|ACCANTO A MINA')]),
 (3, "Partecipa anche a Il paroliere questo sconosciuto, con Mike Bongiorno. E nel 1969 è tra i protagonisti di Doppia coppia, un altro varietà del sabato sera. Il suo stile è sempre lo stesso: ironia, eleganza, pianoforte.", [('paroliere', 'i:quill|IL PAROLIERE QUESTO SCONOSCIUTO'), ('1969', 'cal:DOPPIA COPPIA|1969'), ('ironia', 'iii:tuxedo|ELEGANZA|piano|PIANOFORTE|microphone|IRONIA')]),
 (3, "Ma il programma che lo rende una leggenda è alla radio. Il 6 gennaio 1967, sul secondo programma, debutta la Hit Parade: la classifica settimanale delle canzoni.", [('radio', 'i:radio|ALLA RADIO'), ('gennaio', 'cal:HIT PARADE|6 GENNAIO 1967'), ('Hit', 'i:hitparade|LA CLASSIFICA')]),
 (3, "Va in onda il venerdì all'una del pomeriggio. Luttazzi presenta le prime otto canzoni della classifica. E milioni di italiani si fermano ad ascoltare.", [('venerdì', 'clock:13|VENERDÌ · ORE 13'), ('otto', 'i:hitparade|LE PRIME OTTO'), ('milioni', 'big:milioni|di ascoltatori')]),
 (3, "Secondo un quotidiano, la prima canzone al numero uno, quel giorno, è Bang bang, cantata da Dalida. Secondo un altro, alla Hit Parade a un certo punto si arriva a oltre cinque milioni di ascoltatori.", [('quotidiano', 'i:newspaper|SECONDO UN QUOTIDIANO'), ('Bang', 'i:music|AL NUMERO UNO'), ('cinque', 'big:> 5 mln|di ascoltatori · secondo un quotidiano')]),
 (3, "Secondo una ricostruzione, il suo annuncio, quel Hit Parade gridato con la i allungata, entra nella memoria di una generazione. Nel 1970 Lelio Luttazzi è in cima alla sua carriera. E sta per cadere.", [('annuncio', 'i:microphone|«HIIIT PARADE!»'), ('generazione', 'crowd'), ('cima', 'i:trophy|IN CIMA'), ('cadere', 'stamp:STA PER CADERE')]),
 (3, "Facciamo un conto. Dal debutto della Hit Parade, nel gennaio 1967, all'arresto, nel 1970, passano poco più di tre anni. Tre anni di successo ogni venerdì. E poi, in pochi giorni, tutto cambia.", [('conto', 'h:Un *conto*'), ('1967', 'tl:1967|HIT PARADE;1968|;1969|DOPPIA COPPIA;1970|L\'ARRESTO'), ('tre', 'big:> 3 anni|di Hit Parade prima dell\'arresto')]),
 (3, "Se questa storia ti sta piacendo, iscriviti a Fascicolo Italia: ogni giorno un nuovo caso. E adesso, la telefonata.", [('Se', 'subscribe'), ('telefonata', 'i:phonecall|LA TELEFONATA')]),
 # 04 LA TELEFONATA E L'ARRESTO
 (4, "Ed eccoci alla primavera del 1970. Da tempo la Guardia di Finanza indaga sul giro della cocaina nel mondo dello spettacolo, e ha messo sotto controllo alcuni telefoni.", [('primavera', 'cal:PRIMAVERA|1970'), ('Guardia', 'i:gdf|L\'INDAGINE'), ('cocaina', 'stamp:COCAINA'), ('telefoni', 'i:taperec|I TELEFONI SOTTO CONTROLLO')]),
 (4, "Secondo le ricostruzioni, Walter Chiari si trova a Bologna, in un albergo del centro. Chiama la casa di Luttazzi a Roma, e al telefono parla con la donna che lavora in casa.", [('Bologna', 'map:Bologna|12|Bologna,Roma|Bologna>Roma'), ('albergo', 'i:hotel|UN ALBERGO DI BOLOGNA'), ('casa', 'home:0'), ('donna', 'i:woman|LA DONNA CHE LAVORA IN CASA')]),
 (4, "Chiari le lascia un messaggio: Luttazzi deve chiamare un certo numero, un conoscente. Una richiesta normale, tra amici. Il messaggio arriva.", [('messaggio', 'i:notes|IL MESSAGGIO'), ('numero', 'i:phone|UN NUMERO DA CHIAMARE'), ('normale', 'stamp:UN FAVORE'), ('arriva', 'home:1')]),
 (4, "Secondo un quotidiano romano, quella sera Luttazzi ha ospiti in casa, una festa nel suo attico. Prende il telefono e chiama quel numero, per fare un favore all'amico. Non sa chi sia la persona dall'altra parte.", [('quotidiano', 'i:newspaper|SECONDO UN QUOTIDIANO ROMANO'), ('festa', 'home:0'), ('chiama', 'home:1'), ('sa', 'i:question|CHI È?')]),
 (4, "Ma dall'altra parte c'è proprio l'uomo che la Guardia di Finanza sta controllando. Il suo telefono è intercettato, e la voce di Luttazzi finisce registrata sui nastri degli investigatori.", [('intercettato', 'home:2'), ('registrata', 'i:taperec|SUI NASTRI')]),
 (4, "Cosa si dicono, esattamente? Le fonti che abbiamo consultato non riportano il testo della telefonata. Sappiamo solo che Luttazzi, secondo tutte le ricostruzioni, trasmette il messaggio dell'amico.", [('Cosa', 'h:Cosa si *dicono*?'), ('testo', 'doc:LA TELEFONATA|testo non riportato|dalle fonti consultate|ricostruzione'), ('messaggio', 'flow:CHIARI>LUTTAZZI>SCONOSCIUTO')]),
 (4, "Per gli investigatori, però, quella chiamata ha un altro significato. Un uomo famoso che telefona a uno spacciatore, per conto di un altro uomo famoso. Per loro è un indizio. Anzi, per il pubblico ministero diventerà la prova.", [('investigatori', 'i:magnifier|GLI INVESTIGATORI'), ('famoso', 'ii:music|LUTTAZZI|clapper|CHIARI'), ('indizio', 'stamp:INDIZIO?'), ('prova', 'i:report|«LA PROVA»')]),
 (4, "Facciamo un conto. Una telefonata così dura pochi secondi, forse un minuto. Per quel minuto, Luttazzi passerà in carcere ventisette giorni. Cioè seicentoquarantotto ore.", [('conto', 'i:stopwatch|POCHI SECONDI'), ('ventisette', 'big:27 giorni|per una telefonata'), ('seicentoquarantotto', 'big:648 ore|27 × 24')]),
 (4, "E arriva il giorno dell'arresto. Le fonti non concordano sulla data: per una ricostruzione è il 22 maggio 1970, per altre è giugno. Di sicuro è la fine della primavera del 1970.", [("dell'arresto", 'i:handcuffs|L\'ARRESTO'), ('22', 'cal:L\'ARRESTO|22 MAGGIO 1970?'), ('giugno', 'stamp:DATA NON CONCORDE'), ('primavera', 'cal:FINE PRIMAVERA|1970')]),
 (4, "Gli uomini della Guardia di Finanza si presentano a casa di Luttazzi, vicino alla Fontana di Trevi. Secondo una testimonianza, è l'alba.", [('Guardia', 'home:3'), ('Fontana', 'i:fountain|L\'ATTICO A TREVI'), ("l'alba", 'i:sun|ALL\'ALBA')]),
 (4, "Cercano la droga. Non trovano niente: né cocaina, né altre sostanze. Lo riferiscono un quotidiano romano e la testimonianza della moglie. Ma l'arresto scatta lo stesso.", [('Cercano', 'i:magnifier|LA PERQUISIZIONE'), ('niente', 'stamp:NIENTE'), ('quotidiano', 'ii:newspaper|UN QUOTIDIANO|letter|LA MOGLIE'), ("l'arresto", 'i:handcuffs|ARRESTATO LO STESSO')]),
 (4, "L'accusa è pesantissima: detenzione e spaccio di stupefacenti. Per uno dei presentatori più amati d'Italia, è come un fulmine. E nei giorni dell'indagine viene arrestato anche il suo amico, Walter Chiari.", [("l'accusa", 'doc:L\'ACCUSA|detenzione e spaccio|di stupefacenti|ricostruzione'), ('fulmine', 'h:Un *fulmine*'), ('Chiari', 'ii:handcuffs|LUTTAZZI|handcuffs|CHIARI')]),
 (4, "Secondo un quotidiano toscano, in quelle ore Luttazzi e Chiari stavano per firmare i contratti per condurre la nuova edizione di Canzonissima, il grande programma musicale della televisione. Quei contratti non saranno mai firmati.", [('quotidiano', 'i:newspaper|SECONDO UN QUOTIDIANO'), ('contratti', 'i:signature|I CONTRATTI'), ('Canzonissima', 'i:tvstage|CANZONISSIMA'), ('mai', 'stamp:MAI FIRMATI')]),
 (4, "Facciamo il punto per chi ci raggiunge adesso. Primavera 1970. Un messaggio di Walter Chiari. Una telefonata di Luttazzi a un numero intercettato. La perquisizione: niente. E l'arresto, per spaccio.", [('punto', 'tl:MESSAGGIO|DI CHIARI;TELEFONATA|INTERCETTATA;PERQUISIZIONE|NIENTE;ARRESTO|SPACCIO'), ('niente', 'stamp:NIENTE'), ("l'arresto", 'i:handcuffs|L\'ARRESTO')]),
 # 05 REGINA COELI
 (5, "Luttazzi viene portato a Regina Coeli, il carcere di Roma. Qui lo mettono in una cella d'isolamento. Niente contatti con gli altri detenuti, niente visite.", [('Regina', 'i:prison|REGINA COELI'), ("d'isolamento", 'cella:0'), ('visite', 'stamp:NESSUNA VISITA')]),
 (5, "Secondo la moglie, che ha raccontato questa storia in diverse occasioni, Luttazzi può vedere il suo avvocato solo dopo quindici giorni. Quindici giorni senza poter spiegare a nessuno quella telefonata.", [('moglie', 'i:letter|SECONDO LA MOGLIE'), ('avvocato', 'i:case|L\'AVVOCATO'), ('quindici', 'big:15 giorni|prima di vedere l\'avvocato'), ('spiegare', 'i:question|PERCHÉ?')]),
 (5, "Fuori, intanto, la notizia esplode. I giornali mettono in prima pagina i due nomi famosi accanto alla parola droga. Per il pubblico, i due amici della televisione sono finiti in carcere insieme.", [('notizia', 'i:newspaper|IN PRIMA PAGINA'), ('droga', 'news:CRONACA|Arrestati due volti noti|Indagine sulla droga|RICOSTRUZIONE · TESTATA GENERICA'), ('insieme', 'ii:handcuffs|LUTTAZZI|handcuffs|CHIARI')]),
 (5, "Secondo un'altra ricostruzione, alcuni giornali riportano in modo sbagliato il ruolo di Luttazzi nel caso. E secondo un quotidiano nazionale, anche Enzo Tortora, che allora scriveva su un giornale, commenta il caso. Più tardi scriverà di dovergli molte scuse.", [('giornali', 'i:newspaper|ALCUNI GIORNALI'), ('sbagliato', 'stamp:NOTIZIE SBAGLIATE'), ('Tortora', 'i:microphone|ENZO TORTORA'), ('scuse', 'i:letter|LE SCUSE · SECONDO UN QUOTIDIANO')]),
 (5, "In cella Luttazzi scrive. Su quei giorni prende appunti che diventeranno un libro di memorie, Operazione Montecristo. Il titolo richiama il conte di Montecristo, il prigioniero innocente del romanzo.", [('scrive', 'cella:1'), ('libro', 'i:memoir|RICOSTRUZIONE · NON LA COPERTINA'), ('Montecristo', 'h:Il prigioniero\n*innocente*')]),
 (5, "Secondo una ricostruzione, nel libro racconta l'attesa: ogni mattina pensa che sarà il giorno buono, quello in cui lo faranno uscire. E ogni sera quel giorno non è arrivato.", [("l'attesa", 'i:hourglass|L\'ATTESA'), ('mattina', 'i:sun|OGNI MATTINA'), ('sera', 'i:moon|OGNI SERA')]),
 (5, "Descrive anche la cella. In una citazione riportata da un quotidiano la definisce una cella fetida. Un uomo abituato agli studi della televisione e allo smoking si ritrova in pochi metri quadrati.", [('cella', 'cella:0'), ('fetida', 'h:«Una cella\n*fetida*»'), ('smoking', 'ii:tuxedo|IERI|isolation|OGGI')]),
 (5, "Il tempo passa, un giorno dopo l'altro. Una settimana. Due settimane. Tre. Per un uomo che non ha fatto niente, ogni giorno è lunghissimo.", [('tempo', 'cella:2'), ('settimana', 'big:7|giorni'), ('Tre', 'big:21|giorni'), ('lunghissimo', 'i:hourglass|OGNI GIORNO')]),
 (5, "E Walter Chiari? Anche lui è a Regina Coeli. La sua posizione è diversa da quella di Luttazzi: alla fine sarà condannato per detenzione di cocaina per uso personale. Ma non per spaccio: su questo il tribunale lo proscioglierà.", [('Chiari', 'i:clapper|WALTER CHIARI'), ('diversa', 'flow:LUTTAZZI>CHIARI'), ('uso', 'stamp:USO PERSONALE'), ('tribunale', 'i:court|IL TRIBUNALE')]),
 (5, "Facciamo un conto sul tempo. Ventisette giorni sono quasi un mese intero. Quasi seicentocinquanta ore in una cella, per una telefonata fatta per un amico.", [('conto', 'cella:2'), ('Ventisette', 'big:27 giorni|quasi un mese'), ('telefonata', 'i:phonecall|PER UNA TELEFONATA')]),
 # 06 L'INDAGINE
 (6, "Mentre Luttazzi è in cella, gli investigatori continuano a lavorare. Ascoltano le registrazioni, interrogano, ricostruiscono chi chiamava chi. È il lavoro normale di un'indagine.", [('investigatori', 'i:magnifier|L\'INDAGINE CONTINUA'), ('registrazioni', 'i:taperec|LE REGISTRAZIONI'), ('chi', 'net:3'), ('normale', 'stamp:IL LAVORO NORMALE')]),
 (6, "Ma il punto di partenza era sbagliato. Una telefonata non dice cosa sa chi la fa. Luttazzi aveva chiamato quel numero senza sapere chi fosse quell'uomo, e senza sapere che cosa facesse.", [('sbagliato', 'stamp:IL PUNTO DEBOLE'), ('telefonata', 'i:phonecall|UNA TELEFONATA'), ('sapere', 'i:question|LUI NON SAPEVA')]),
 (6, "Secondo le fonti, l'inchiesta della Guardia di Finanza riguarda tre nomi famosi del mondo dello spettacolo. Due vengono arrestati: Chiari e Luttazzi. Il terzo nome non lo diremo, perché non ci risultano accuse confermate nei suoi confronti.", [('tre', 'iii:nophoto|1|nophoto|2|nophoto|3'), ('arrestati', 'ii:handcuffs|CHIARI|handcuffs|LUTTAZZI'), ('terzo', 'i:nophoto|NESSUN NOME')]),
 (6, "Pensiamo per un momento a come funziona un'intercettazione. Gli investigatori ascoltano tutte le chiamate di un numero. Chi chiama, chi risponde, a che ora. Ma una voce su un nastro non dice perché una persona ha chiamato.", [('Pensiamo', 'h:Come funziona\nun\'*intercettazione*'), ('ascoltano', 'net:4'), ('ora', 'clock:21|A CHE ORA'), ('perché', 'i:question|E PERCHÉ?')]),
 (6, "Nel caso di Luttazzi, il perché c'era: un favore all'amico. Un messaggio passato da una persona all'altra. Per capirlo bastava ascoltare la sua versione, e verificarla.", [('perché', 'flow:CHIARI>LUTTAZZI'), ('messaggio', 'i:notes|UN MESSAGGIO'), ('verificarla', 'i:shield_ok|VERIFICARE')]),
 (6, "Proviamo a metterci nei suoi panni. Un amico ti fa sapere che devi chiamare qualcuno. Tu chiami, riferisci, riattacchi. Non ci pensi più. Qualche giorno dopo, quella chiamata è la ragione per cui sei in carcere.", [('panni', 'h:Nei suoi *panni*'), ('chiami', 'home:1'), ('riattacchi', 'i:phone|FINE DELLA CHIAMATA'), ('carcere', 'cella:0')]),
 (6, "E da dentro una cella d'isolamento, senza avvocato per due settimane secondo la moglie, è difficile perfino raccontare questa semplice verità a qualcuno che possa verificarla.", [("d'isolamento", 'i:isolation|IN ISOLAMENTO'), ('avvocato', 'big:15 giorni|senza avvocato · secondo la moglie'), ('verificarla', 'i:question|CHI ASCOLTA?')]),
 (6, "Ed è qui che il caso diventa un errore. Non perché qualcuno abbia inventato una prova, ma perché una prova debole ha portato in carcere un uomo prima di essere verificata.", [('errore', 'stamp:L\'ERRORE'), ('debole', 'i:report|UNA PROVA DEBOLE'), ('carcere', 'i:prison|PRIMA IL CARCERE'), ('verificata', 'i:magnifier|POI LA VERIFICA')]),
 (6, "Intanto la televisione si muove. Secondo diverse fonti, la Rai lo allontana dai suoi programmi. Il volto della Hit Parade e del sabato sera, ora è un nome scomodo.", [('televisione', 'i:tv|LA TELEVISIONE'), ('Rai', 'stamp:ALLONTANATO'), ('Hit', 'i:hitparade|LA HIT PARADE'), ('scomodo', 'h:Un nome\n*scomodo*')]),
 (6, "Su cosa succede alla sua Hit Parade le fonti non concordano. Per una associazione di vittime della malagiustizia gli viene tolta. Per un quotidiano nazionale, la conduzione passa a Renzo Arbore. Per un quotidiano romano, la Rai in seguito gliela restituisce in parte.", [('Hit', 'i:hitparade|LA HIT PARADE'), ('tolta', 'stamp:VERSIONI DIVERSE'), ('Arbore', 'i:microphone|SECONDO UN QUOTIDIANO'), ('restituisce', 'i:radio|SECONDO UN ALTRO')]),
 (6, "Riepilogo per chi entra adesso. Luttazzi è in isolamento a Regina Coeli. La prova contro di lui è una telefonata. Nella sua casa non è stato trovato niente. E fuori il suo nome è sui giornali accanto alla parola droga.", [('Riepilogo', 'tl:TELEFONATA|;ARRESTO|;ISOLAMENTO|;GIORNALI|'), ('telefonata', 'i:phonecall|LA PROVA?'), ('niente', 'stamp:NIENTE IN CASA'), ('giornali', 'i:newspaper|SUI GIORNALI')]),
 # 07 LA SVOLTA
 (7, "Dopo qualche settimana gli inquirenti arrivano alla conclusione che avrebbero potuto raggiungere molto prima: Luttazzi non c'entra niente.", [('settimana', 'cella:2'), ('conclusione', 'i:report|LA CONCLUSIONE'), ('niente', 'stamp:NON C\'ENTRA NIENTE')]),
 (7, "La sua posizione viene chiarita. Dopo ventisette giorni la porta della cella si apre, e Luttazzi esce da Regina Coeli. È libero.", [('chiarita', 'i:shield_ok|POSIZIONE CHIARITA'), ('ventisette', 'big:27|giorni dopo'), ('porta', 'cella:3'), ('libero', 'h:*Libero*')]),
 (7, "La formula, secondo le fonti italiane, è la più netta: completa estraneità ai fatti. Viene prosciolto completamente. Per un quotidiano toscano, viene riabilitato con tante scuse.", [('formula', 'doc:IL PROSCIOGLIMENTO|completa estraneità|ai fatti|ricostruzione'), ('prosciolto', 'stamp:PROSCIOLTO'), ('scuse', 'i:letter|«CON TANTE SCUSE»')]),
 (7, "Un giornalista, in un articolo di commento, scrive che per prendere atto della sua innocenza ci è voluto un mese. E lo definisce un clamoroso errore giudiziario.", [('giornalista', 'i:quill|UN COMMENTO'), ('mese', 'big:≈ 1 mese|per capire'), ('clamoroso', 'stamp:ERRORE GIUDIZIARIO')]),
 (7, "Ma la libertà non cancella quello che è successo. Il suo nome è stato sui giornali accanto alla droga. E una smentita, si sa, fa sempre meno rumore di un arresto.", [('libertà', 'i:key|LIBERO'), ('giornali', 'i:newspaper|IL NOME SUI GIORNALI'), ('smentita', 'ii:megaphone|L\'ARRESTO|ear|LA SMENTITA')]),
 (7, "Pensiamo a cosa significa uscire, in quel momento. Fuori ci sono i giornalisti, i fotografi, i conoscenti. Ognuno ha letto qualcosa. E non tutti leggeranno la notizia del proscioglimento.", [('uscire', 'cella:3'), ('giornalisti', 'iii:camera|FOTOGRAFI|newspaper|GIORNALISTI|family|CONOSCENTI'), ('proscioglimento', 'ii:newspaper|L\'ARRESTO|newspaper|IL PROSCIOGLIMENTO')]),
 (7, "È lo stesso meccanismo che vedremo, tredici anni dopo, nel caso di Enzo Tortora: un nome famoso, un'accusa infamante, la prima pagina. E poi un'assoluzione che arriva tardi, e che non restituisce quello che è stato perso.", [('meccanismo', 'h:Lo stesso\n*meccanismo*'), ('Tortora', 'ii:music|LUTTAZZI · 1970|microphone|TORTORA · 1983'), ('perso', 'stamp:IL DANNO RESTA')]),
 (7, "Luttazzi ne parlerà con parole amare. In una citazione riportata da una ricostruzione, dice che per lui è stato come morire dentro. In un'altra, riportata da un quotidiano, che quella vicenda è stata determinante per la sua fragilità nell'affrontare la vita.", [('amare', 'h:Parole\n*amare*'), ('morire', 'stamp:«MORIRE DENTRO»'), ('fragilità', 'i:question|LA FRAGILITÀ')]),
 (7, "Facciamo un conto. Ventisette giorni su quarantasette anni di vita sono poco più dello zero virgola quindici per cento. Un tempo minuscolo. Ma il segno che lasciano durerà per i quarant'anni successivi.", [('conto', 'h:Un *conto*'), ('Ventisette', 'big:0,16%|27 giorni su 47 anni'), ('quarant', 'big:40 anni|di conseguenze')]),
 # 08 IL PROCESSO E LE SENTENZE
 (8, "Vediamo ora cosa risulta dalle decisioni dei giudici. Partiamo da Luttazzi. Per lui non c'è nessuna condanna: viene prosciolto perché estraneo ai fatti.", [('giudici', 'court:LE DECISIONI'), ('Luttazzi', 'card:LELIO LUTTAZZI|prosciolto|estraneo ai fatti'), ('condanna', 'stamp:NESSUNA CONDANNA')]),
 (8, "C'è una sola voce diversa. Una enciclopedia online in lingua inglese parla di un'assoluzione per mancanza di prove. Le fonti italiane, invece, parlano di proscioglimento completo. Le versioni non coincidono.", [('enciclopedia', 'i:oldbook|UNA ENCICLOPEDIA IN INGLESE'), ('mancanza', 'stamp:VERSIONI DIVERSE'), ('italiane', 'i:newspaper|LE FONTI ITALIANE')]),
 (8, "E Walter Chiari? La sua strada giudiziaria è più lunga. In primo grado viene prosciolto dall'accusa di spaccio, ma condannato con la condizionale per la detenzione di cocaina per uso personale.", [('Chiari', 'i:clapper|WALTER CHIARI'), ('spaccio', 'doc:PRIMO GRADO|prosciolto dallo spaccio|condannato per uso personale|ricostruzione'), ('condizionale', 'stamp:CONDIZIONALE')]),
 (8, "Secondo una ricostruzione, all'inizio Chiari aveva ammesso di aver avuto un grammo di cocaina, su consiglio di un ufficiale, e il giorno dopo aveva ritrattato, pentendosi di quella leggerezza.", [('ricostruzione', 'stamp:SECONDO UNA RICOSTRUZIONE'), ('grammo', 'big:1 grammo|secondo Chiari'), ('ritrattato', 'i:quill|LA RITRATTAZIONE')]),
 (8, "Nel 1977 Chiari ottiene la riabilitazione, come confermano due ricostruzioni diverse. Ma anche per lui il danno è fatto: per anni la Rai non lo chiamerà più.", [('1977', 'cal:LA RIABILITAZIONE|1977'), ('danno', 'stamp:IL DANNO È FATTO'), ('Rai', 'i:tv|PER ANNI FUORI DALLA RAI')]),
 (8, "E l'uomo del telefono intercettato? Non ne diciamo il nome, e le fonti che abbiamo consultato non riportano l'esito della sua vicenda giudiziaria. Per questo non diciamo altro su di lui.", [('telefono', 'i:taperec|IL TELEFONO INTERCETTATO'), ('nome', 'i:nophoto|NESSUN NOME'), ("l'esito", 'stamp:ESITO NON RIPORTATO')]),
 (8, "Luttazzi, intanto, comincia un'altra battaglia: quella contro chi ha scritto di lui. Ogni volta che il suo nome viene accostato alla droga, querela. E secondo le fonti, vince sempre.", [('battaglia', 'h:Un\'altra *battaglia*'), ('querela', 'i:law|LE QUERELE'), ('vince', 'iii:scalesok|VINTA|scalesok|VINTA|scalesok|VINTA')]),
 (8, "La moglie racconterà che tra querele e cause civili non ne ha persa nessuna. E secondo un quotidiano nazionale, con i soldi vinti in tribunale si compra una barca, che chiama Oblomov, come il personaggio del romanzo russo che non vuole alzarsi dal letto.", [('moglie', 'i:letter|SECONDO LA MOGLIE'), ('nessuna', 'big:0|cause perse'), ('barca', 'i:sailboat|LA BARCA OBLOMOV'), ('letto', 'i:bed|IL PERSONAGGIO DI OBLOMOV')]),
 (8, "Un dettaglio che dice molto. Oblomov, nel romanzo, è un uomo che rinuncia al mondo e si ritira nella sua stanza. E il mondo dello spettacolo, Luttazzi, comincia proprio ad abbandonarlo.", [('dettaglio', 'h:Un *dettaglio*'), ('rinuncia', 'i:bed|CHI RINUNCIA AL MONDO'), ('abbandonarlo', 'stamp:IL RITIRO')]),
 (8, "Riassumiamo le decisioni. Luttazzi: prosciolto, nessuna condanna. Chiari: prosciolto dallo spaccio, condannato per uso personale, poi riabilitato. Le querele di Luttazzi contro chi lo aveva accostato alla droga: vinte.", [('Riassumiamo', 'tl:LUTTAZZI|PROSCIOLTO;CHIARI|USO PERSONALE;1977|RIABILITATO;QUERELE|VINTE'), ('vinte', 'stamp:VINTE')]),
 # 09 COSA È SUCCESSO DOPO
 (9, "Dopo il carcere, secondo diverse fonti, qualcosa dentro di lui si rompe. Lo chiamano sempre meno. L'ambiente è diventato ostile. E lui si allontana dalla vita pubblica.", [('carcere', 'i:prison|DOPO IL CARCERE'), ('rompe', 'stamp:QUALCOSA SI ROMPE'), ('meno', 'i:phone|LO CHIAMANO SEMPRE MENO'), ('allontana', 'fig:suit')]),
 (9, "Ma prima di sparire fa una cosa che pochi conoscono. Nel 1972 scrive e dirige un film, il suo unico film da regista: L'illazione. Il titolo, una parola che indica una conclusione tratta da indizi, non è un caso.", [('pochi', 'i:question|POCHI LO SANNO'), ('1972', 'cal:L\'ILLAZIONE|1972'), ('film', 'i:filmreel|IL SUO UNICO FILM'), ("l'illazione", 'h:L\'*illazione*')]),
 (9, "Secondo la scheda di un sito di cinema, la storia ricorda un racconto di Dürrenmatt rovesciato: un giudice, a una cena, sospetta degli altri commensali. Il sospetto, ancora una volta, al centro.", [('scheda', 'i:clapper|SECONDO UN SITO DI CINEMA'), ('giudice', 'i:court|UN GIUDICE'), ('cena', 'i:plate|UNA CENA'), ('sospetto', 'stamp:IL SOSPETTO')]),
 (9, "Il film viene prodotto dalla Rai. Ma non viene mai trasmesso. Resta chiuso in un archivio per quasi quarant'anni.", [('Rai', 'i:tv|PRODOTTO DALLA RAI'), ('mai', 'stamp:MAI TRASMESSO'), ('archivio', 'i:filmreel|IN ARCHIVIO'), ('quarant', 'big:≈ 39 anni|in un archivio')]),
 (9, "C'è poi un altro film legato a questa storia. Secondo diverse ricostruzioni, il libro Operazione Montecristo ispira in parte Alberto Sordi per un film sulla detenzione in attesa di giudizio, Detenuto in attesa di giudizio.", [('altro', 'i:clapper|UN ALTRO FILM'), ('Montecristo', 'i:memoir|RICOSTRUZIONE · NON LA COPERTINA'), ('Sordi', 'flow:IL LIBRO>IL FILM DI SORDI'), ('Detenuto', 'h:*Detenuto*\nin attesa di giudizio')]),
 (9, "Gli anni Settanta e Ottanta, per Luttazzi, sono anni di apparizioni sempre più rare. Qualche ritorno, sempre con i musicisti amici, ma lontano dal centro della scena.", [('Settanta', 'tl:1970|;1975|;1980|;1985|;1990|'), ('rare', 'i:hourglass|APPARIZIONI RARE'), ('musicisti', 'i:piano|CON I MUSICISTI AMICI')]),
 (9, "Nel 2003, per i suoi ottant'anni, un quotidiano romano scrive che da più di trent'anni ha preferito l'oblio, e che è diventato semplicemente un pensionato.", [('2003', 'cal:80 ANNI|2003'), ("l'oblio", 'h:L\'*oblio*'), ('pensionato', 'i:house|UN PENSIONATO')]),
 (9, "Poi, negli anni Duemila, arriva una sorpresa. Fiorello lo riporta davanti al pubblico, prima alla radio e poi sul palco. E poco dopo Fabio Fazio lo invita in televisione.", [('Duemila', 'cal:IL RITORNO|ANNI 2000'), ('Fiorello', 'i:microphone|FIORELLO'), ('pubblico', 'i:radio|PRIMA ALLA RADIO'), ('Fazio', 'i:tvcam|IN TELEVISIONE')]),
 (9, "Le nuove generazioni, che non sapevano nulla di lui, scoprono un pianista ironico ed elegante, ultraottantenne, che suona lo swing come sessant'anni prima.", [('generazioni', 'crowd'), ('pianista', 'i:piano|IL PIANISTA'), ('swing', 'i:music|LO SWING')]),
 (9, "Nel 2009 sale sul palco del Festival di Sanremo, accanto alla giovane cantante Arisa, con la canzone Sincerità. Quell'anno Arisa vince tra le nuove proposte. Sarà, secondo un quotidiano, la sua ultima volta in televisione.", [('2009', 'map:Sanremo|20|Sanremo'), ('Arisa', 'i:microphone|ARISA · SINCERITÀ'), ('vince', 'i:trophy|NUOVE PROPOSTE'), ('ultima', 'stamp:L\'ULTIMA VOLTA')]),
 (9, "Facciamo un conto. Dall'arresto del 1970 al palco di Sanremo nel 2009 passano trentanove anni. Gli stessi trentanove anni che il suo film ha passato in un archivio, dal 1972 al 2011.", [('conto', 'h:Un *conto*'), ('trentanove', 'big:39 anni|dal carcere a Sanremo'), ('archivio', 'big:39 anni|dal film alla prima tv')]),
 (9, "Negli ultimi anni torna a vivere a Trieste, la sua città. Muore lì, nella notte, il giorno 8 luglio 2010, nella sua casa, a ottantasette anni, assistito dalla moglie Rossana.", [('Trieste', 'map:Trieste|40|Roma,Trieste|Roma>Trieste'), ('luglio', 'cal:TRIESTE|8 LUGLIO 2010'), ('ottantasette', 'big:87 anni')]),
 (9, "Il sindaco di Trieste fa allestire la camera ardente nella sala del consiglio comunale. Le sue ceneri, come aveva chiesto, vengono disperse in mare.", [('sindaco', 'h:Il *Comune*\ndi Trieste'), ('camera', 'i:family|L\'ULTIMO SALUTO'), ('mare', 'i:sea|DISPERSE IN MARE')]),
 (9, "Dopo la sua morte, durante un trasloco, la moglie ritrova L'illazione. Il film viene restaurato e nel 2011 viene presentato alla Festa del cinema di Roma. Il film che nessuno aveva visto, finalmente sullo schermo.", [('morte', 'i:boxbooks|UN TRASLOCO'), ('restaurato', 'i:filmreel|IL RESTAURO'), ('2011', 'cal:FESTA DEL CINEMA DI ROMA|2011'), ('schermo', 'i:cinema|FINALMENTE SULLO SCHERMO')]),
 (9, "Nel 2022 il regista Giorgio Verdelli gli dedica un documentario, Souvenir d'Italie, presentato alla Festa del cinema di Roma e trasmesso da Rai Tre nel marzo 2023, a poche settimane dai cento anni dalla nascita.", [('2022', 'cal:IL DOCUMENTARIO|2022'), ('Souvenir', 'i:filmreel|SOUVENIR D\'ITALIE'), ("rai", 'i:tv|RAI3 · MARZO 2023'), ('cento', 'big:100 anni|dalla nascita · 2023')]),
 (9, "Nel documentario lo ricordano, tra gli altri, Fiorello, Fabio Fazio, Stefano Bollani, Pupi Avati e Drusilla Foer, insieme alla moglie Rossana e alla figlia Donatella. Un omaggio di colleghi di generazioni diverse.", [('documentario', 'i:filmreel|SOUVENIR D\'ITALIE'), ('Fiorello', 'iii:microphone|FIORELLO|tvcam|FAZIO|piano|BOLLANI'), ('Avati', 'ii:clapper|PUPI AVATI|microphone|DRUSILLA FOER'), ('generazioni', 'crowd')]),
 (9, "Nel 2023, per i cento anni dalla nascita, i giornali tornano a scrivere di lui. Un quotidiano nazionale lo chiama lo showman vittima dell'ingiustizia, e ricorda i ventisette giorni passati in carcere da innocente.", [('2023', 'cal:100 ANNI|27 APRILE 2023'), ('giornali', 'i:newspaper|I GIORNALI'), ('showman', 'h:«Showman vittima\n*dell\'ingiustizia*»'), ('ventisette', 'big:27 giorni|da innocente')]),
 (9, "Un magistrato, Santino Mirabella, ha definito quello che è successo nel 1970 un orrore giudiziario. E la moglie Rossana lo chiama, con parole semplici, una stramaledetta vicenda.", [('magistrato', 'i:court|UN MAGISTRATO'), ('orrore', 'stamp:«ORRORE GIUDIZIARIO»'), ('Rossana', 'i:letter|LA MOGLIE'), ('stramaledetta', 'h:«Una *stramaledetta*\nvicenda»')]),
 (9, "Riepilogo per chi entra adesso. 1970: ventisette giorni in carcere, poi il proscioglimento. Poi il ritiro, il film mai trasmesso, le querele vinte. Negli anni Duemila il ritorno, Sanremo, e nel 2010 la morte a Trieste.", [('Riepilogo', 'tl:1970|27 GIORNI;1972|IL FILM;2009|SANREMO;2010|TRIESTE'), ('ritiro', 'stamp:IL RITIRO'), ('Trieste', 'i:sea|TRIESTE')]),
 # 10 LE DOMANDE APERTE
 (10, "Come in ogni caso, restano punti su cui le fonti raccontano versioni diverse. Vediamoli uno per uno.", [('punti', 'h:Le domande\n*aperte*'), ('versioni', 'stamp:VERSIONI DIVERSE')]),
 (10, "Primo: la data dell'arresto. Per una ricostruzione dettagliata è il 22 maggio 1970. Per un'associazione di vittime e per un giornalista è giugno. Per un quotidiano toscano, semplicemente la fine della primavera.", [('Primo', 'cal:22 MAGGIO?|GIUGNO?'), ('22', 'i:calendar_x|22 MAGGIO?'), ('giugno', 'i:calendar_x|GIUGNO?'), ('primavera', 'stamp:NON CONCORDE')]),
 (10, "Secondo: quanti giorni. Quasi tutte le fonti dicono ventisette. Una enciclopedia dice un mese. Una testimonianza riportata da un sito parla addirittura di quaranta giorni. Noi abbiamo usato il numero confermato dalla maggior parte delle fonti: ventisette.", [('Secondo', 'big:27?|giorni'), ('mese', 'iii:hourglass|27 GIORNI|hourglass|UN MESE|hourglass|40 GIORNI?'), ('ventisette', 'stamp:27 · LA MAGGIOR PARTE')]),
 (10, "Terzo: la formula. Proscioglimento per completa estraneità ai fatti, secondo le fonti italiane. Assoluzione per mancanza di prove, secondo una enciclopedia in inglese. Due formule molto diverse per il destino di un uomo.", [('formula', 'ii:shield_ok|ESTRANEITÀ|question|MANCANZA DI PROVE?'), ('diverse', 'stamp:DUE FORMULE')]),
 (10, "Quarto: la Hit Parade. Gli è stata tolta? È passata ad altri? Gli è stata restituita, almeno in parte? Le fonti raccontano tre cose diverse, e non abbiamo trovato una data sicura per la fine della sua conduzione.", [('Hit', 'i:hitparade|LA HIT PARADE'), ('tolta', 'iii:question|TOLTA?|question|PASSATA AD ALTRI?|question|RESTITUITA?'), ('data', 'stamp:DATA NON TROVATA')]),
 (10, "Quinto: la prima canzone, Il giovanotto matto. Scritta durante la guerra o alla fine degli anni Trenta? E i primi diritti d'autore: trecentocinquantamila lire per alcune fonti, trecentosessantamila per un'altra.", [('Quinto', 'i:music|IL GIOVANOTTO MATTO'), ('Trenta', 'stamp:ANNO NON CONCORDE'), ('trecentocinquantamila', 'ii:coin|350.000|coin|360.000')]),
 (10, "E poi c'è la domanda più grande: perché ci sono voluti ventisette giorni? Perché una persona trovata senza niente in casa è rimasta così a lungo in isolamento? Le fonti che abbiamo consultato non lo spiegano.", [('grande', 'h:La domanda\n*più grande*'), ('ventisette', 'cella:2'), ('isolamento', 'i:isolation|PERCHÉ COSÌ A LUNGO?'), ('spiegano', 'stamp:NESSUNA SPIEGAZIONE')]),
 (10, "Di sicuro sappiamo questo: un uomo innocente è stato privato della libertà per quasi un mese, e il suo nome è stato legato alla droga davanti a tutta l'Italia. E questo, nessuna sentenza poteva cancellarlo.", [('innocente', 'stamp:INNOCENTE'), ('libertà', 'big:≈ 1 mese|senza libertà'), ("l'italia", 'crowd'), ('cancellarlo', 'i:newspaper|IL NOME SUI GIORNALI')]),
 # 11 LA LEZIONE
 (11, "Questa storia non riguarda solo le persone famose. Riguarda chiunque. Ecco cinque idee che il caso Luttazzi ci lascia.", [('famose', 'i:microphone|NON SOLO I FAMOSI'), ('chiunque', 'crowd'), ('cinque', 'big:5 idee')]),
 (11, "Prima idea: la presunzione di innocenza. La Costituzione italiana, all'articolo 27, dice che l'imputato non è considerato colpevole fino alla condanna definitiva. Un arresto non è una condanna.", [('Prima', 'check:1'), ('Costituzione', 'i:law|COSTITUZIONE · ART. 27'), ('condanna', 'stamp:ARRESTO ≠ CONDANNA')]),
 (11, "Seconda idea: un'intercettazione è un indizio, non una sentenza. Una voce su un nastro dice che una telefonata c'è stata, non perché. Va sempre verificata con altri elementi.", [('Seconda', 'check:2'), ("un'intercettazione", 'i:taperec|UN INDIZIO'), ('verificata', 'i:magnifier|DA VERIFICARE')]),
 (11, "Terza idea: attenzione a cosa si fa per conto di altri. Passare un messaggio sembra innocuo. Se un amico ti chiede di chiamare qualcuno che non conosci, è legittimo chiedere chi è e perché.", [('Terza', 'check:3'), ('messaggio', 'i:notes|UN MESSAGGIO PER ALTRI'), ('chiedere', 'i:question|CHI È? PERCHÉ?')]),
 (11, "Quarta idea: chi viene detenuto ingiustamente ha dei diritti. Oggi il codice di procedura penale, all'articolo 314, prevede la riparazione per l'ingiusta detenzione. La domanda va presentata entro due anni.", [('Quarta', 'check:4'), ('314', 'doc:ART. 314 C.P.P.|riparazione per|l\'ingiusta detenzione|sintesi · non il testo integrale'), ('due', 'big:2 anni|per la domanda')]),
 (11, "Quinta idea: anche il pubblico ha una responsabilità. Leggere un titolo non significa sapere com'è andata. Una smentita merita la stessa attenzione di un arresto.", [('Quinta', 'check:5'), ('titolo', 'i:newspaper|UN TITOLO NON È UNA SENTENZA'), ('smentita', 'ii:megaphone|L\'ARRESTO|megaphone|LA SMENTITA')]),
 # IL VERDETTO
 (12, "Siamo al verdetto. Riassumiamo questo fascicolo in sei punti.", [('verdetto', 'cover'), ('sei', 'big:6 punti|il riepilogo')]),
 (12, "Uno: Lelio Luttazzi, triestino, musicista e conduttore, nel 1970 è uno dei volti più amati della radio e della televisione. Due: su richiesta dell'amico Walter Chiari, telefona a un conoscente che non sa essere uno spacciatore, e quel telefono è intercettato.", [('Uno', 'i:piano|1 · IL MUSICISTA'), ('Due', 'i:phonecall|2 · LA TELEFONATA'), ('intercettato', 'i:taperec|INTERCETTATO')]),
 (12, "Tre: arrestato per spaccio, senza che in casa sia trovato niente, passa ventisette giorni in isolamento a Regina Coeli. Quattro: viene prosciolto, completamente estraneo ai fatti.", [('Tre', 'i:isolation|3 · 27 GIORNI'), ('Quattro', 'i:shield_ok|4 · PROSCIOLTO')]),
 (12, "Cinque: la sua carriera non si riprende. Si ritira, vince tutte le querele, il suo unico film resta in un archivio per decenni. Sei: negli anni Duemila torna, fino al palco di Sanremo, e muore a Trieste nel 2010.", [('Cinque', 'i:radio|5 · IL RITIRO'), ('film', 'i:filmreel|IL FILM IN ARCHIVIO'), ('Sei', 'i:microphone|6 · IL RITORNO'), ('Trieste', 'i:sea|TRIESTE · 2010')]),
 (12, "E ora tocca a te. Secondo te, cosa avrebbe dovuto fare la giustizia, in quei giorni del 1970, prima di arrestare un uomo per una telefonata? Scrivilo nei commenti.", [('tocca', 'h:Tocca a *te*'), ('telefonata', 'i:phonecall|PER UNA TELEFONATA'), ('commenti', 'i:quill|SCRIVILO NEI COMMENTI')]),
 (12, "Iscriviti a Fascicolo Italia: ogni giorno un nuovo caso.", [('Iscriviti', 'subscribe')]),
]
